-- -------------------------------------------------------------
-- AptRun AWS Database Update: AptBot Tables & Seed Data
-- Date: 2026-11-23
-- Tables: apt_bot_faqs, support_tickets
-- -------------------------------------------------------------

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 1. Create table apt_bot_faqs
CREATE TABLE IF NOT EXISTS `apt_bot_faqs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `category` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category_label` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category_icon` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'HelpCircle',
  `question` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `answer` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `action_label` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `action_url` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `related_slugs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`related_slugs`)),
  `display_order` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `apt_bot_faqs_slug_unique` (`slug`),
  KEY `apt_bot_faqs_category_index` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. Create table support_tickets
CREATE TABLE IF NOT EXISTS `support_tickets` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `ticket_number` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subject` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `resolved_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `support_tickets_ticket_number_unique` (`ticket_number`),
  KEY `support_tickets_email_index` (`email`),
  KEY `support_tickets_user_id_foreign` (`user_id`),
  CONSTRAINT `support_tickets_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. Seed apt_bot_faqs with verified knowledge nodes
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('about_aptrun', 'About AptRun', 'Brain', 'What is AptRun and how does it help me get placed?', 'what-is-aptrun', 'AptRun is India\'s leading campus placement and engineering readiness sandbox. It brings together everything you need to crack tier-1 tech placements:\n\n• **Practice Arena**: Hundreds of handpicked DSA coding problems organized by core pattern and company tags.\n• **Learning Centre & Articles**: In-depth theoretical articles and system design patterns from first principles.\n• **Mock AI Interviews**: Interactive voice interviews with real-time speech transcription and industry rubric feedback.\n• **Vault AI Interview**: High-stakes AI interview simulation that unlocks candidate verification for hiring partners.\n• **Performance Report**: Real-time evaluation of your coding speed, accuracy, and interview communication.', 'Explore Practice Arena', '/dashboard/practice', '[\"what-is-readiness-score\",\"what-is-project-lab\"]', 1, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('about_aptrun', 'About AptRun', 'Brain', 'What is the AptRun Readiness Score?', 'what-is-readiness-score', 'The **Readiness Score (0–100%)** is your comprehensive hiring readiness benchmark evaluated across 4 core vectors:\n\n1. **Problem Solving (DSA)**: Algorithmic correctness, time/space complexity, and consistency.\n2. **Technical Breadth**: Core CS fundamentals, operating systems, DBMS, and system design.\n3. **Soft Skills & Aptitude**: Speed and accuracy in quantitative, logical, and situational questions.\n4. **Interview Articulation**: Voice-clarity, structure, and technical depth in AI interviews.\n\nA Readiness Score of **60% or above** unlocks direct recruiter recommendations on Mellow Vault.', 'View Performance Report', '/dashboard/reports', '[\"what-is-aptrun\",\"vault-ai-60-percent-qualification\"]', 2, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('about_aptrun', 'About AptRun', 'Brain', 'What is Project Lab and how does it work?', 'what-is-project-lab', 'Project Lab gives you end-to-end, production-grade software development projects designed to make your resume stand out to technical interviewers.\n\nEach project includes:\n• Architectural blueprints and database schema designs.\n• Milestone-by-milestone guided tasks with live code editors.\n• System design explanations and real-world deployment considerations.', 'Open Project Lab', '/dashboard/projects', '[\"what-is-aptrun\"]', 3, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('vault_ai', 'Vault AI Interview', 'ShieldCheck', 'What is the Vault AI Interview?', 'what-is-vault-ai-interview', 'The **Vault AI Interview** is AptRun\'s flagship candidate qualification interview. Unlike practice mock rounds, Vault AI tests simulate live high-stakes company hiring interviews:\n\n• **Structure**: Series containing 3 progressive sets testing technical fundamentals, architecture, and live problem solving.\n• **Proctoring**: Fullscreen locking, webcam/mic verification, and tab-switch monitoring to guarantee honest performance.\n• **Evaluation**: Multidimensional AI scoring analyzing technical accuracy, response depth, and communication delivery.', 'Go to Vault AI Interview', '/dashboard/vault-interviews', '[\"vault-ai-60-percent-qualification\",\"vault-ai-retakes\"]', 10, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('vault_ai', 'Vault AI Interview', 'ShieldCheck', 'Why is 60%+ the qualification score in Vault AI Interview?', 'vault-ai-60-percent-qualification', 'Scoring **60% or higher** in the Vault AI Interview is the benchmark required by our corporate hiring partners on Mellow Vault:\n\n• **Verified for Hiring Badge**: Reaching 60%+ unlocks the verified badge on your profile.\n• **Recruiter Visibility**: Verified profiles are directly indexed for top tech employers and recruiting teams seeking pre-vetted engineers.\n• **Fast-Tracked Shortlisting**: Companies skip preliminary screening rounds and invite verified candidates directly to final technical/HR rounds.', 'Start Vault AI Interview', '/dashboard/vault-interviews', '[\"direct-candidates-mellow-vault\",\"vault-ai-retakes\"]', 11, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('vault_ai', 'Vault AI Interview', 'ShieldCheck', 'Can I retake the Vault AI Interview if I scored below 60%?', 'vault-ai-retakes', 'Yes! If you scored below 60%, you can review your AI feedback rubric, practice weak topics in the Mock AI Interview or Practice Arena, and reattempt:\n\n• Your highest achieved score is preserved on your profile.\n• We recommend practicing in Mock AI Interview before re-attempting your next Vault set.', 'Practice Mock Interviews', '/dashboard/interviews', '[\"what-is-vault-ai-interview\",\"vault-ai-60-percent-qualification\"]', 12, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('placement_drives', 'Placement Drives & Mellow Vault', 'Briefcase', 'Why do direct AptRun candidates not see campus drives on Upcoming Drives?', 'direct-candidates-campus-drives-explained', 'Campus placement drives on the **Upcoming Drives** page are exclusive drives opened directly by partner college placement cells (TPOs) for their enrolled students.\n\nIf you are an independent/direct AptRun member:\n• You get hired off-campus through **Mellow Vault**!\n• Complete the **Vault AI Interview** with **60%+** to be verified for hiring.\n• Once verified, our network of hiring partners accesses your profile directly on Mellow Vault.', 'Learn About Mellow Vault', '/dashboard/vault', '[\"direct-candidates-mellow-vault\",\"future-hiring-on-aptrun\"]', 20, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('placement_drives', 'Placement Drives & Mellow Vault', 'Briefcase', 'How do independent users get hired through Mellow Vault?', 'direct-candidates-mellow-vault', 'Mellow Vault is the off-campus hiring partner network for AptRun members:\n\n1. **Profile Setup**: Your AptRun profile connects directly to Mellow Vault.\n2. **Verification Milestone**: Score **60% or higher** in the **Vault AI Interview**.\n3. **Employer Outreach**: Hiring partners browse verified profiles, review interview scores, and extend interview invites directly.', 'Open Mellow Vault', '/dashboard/vault', '[\"vault-ai-60-percent-qualification\",\"future-hiring-on-aptrun\"]', 21, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('placement_drives', 'Placement Drives & Mellow Vault', 'Briefcase', 'Will hiring partners also recruit directly on AptRun in the future?', 'future-hiring-on-aptrun', 'Yes! In the near future, hiring partners and tech recruiters will also host recruitment drives and hackathons directly on AptRun!\n\nTo make sure you are prioritized when direct AptRun drives open:\n• Keep solving daily DSA problems in the Practice Arena.\n• Achieve 60%+ in Vault AI Interview sets.\n• Keep your Readiness Score above 70%.', 'Practice on AptRun', '/dashboard/practice', '[\"direct-candidates-mellow-vault\",\"what-is-readiness-score\"]', 22, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('mock_interviews', 'Mock AI Voice Interviews', 'Mic', 'How do Mock AI Voice Interviews work?', 'how-mock-interviews-work', 'Mock AI Interviews replicate real technical screening and HR rounds using conversational AI:\n\n• Choose your domain (Backend, Frontend, Full Stack, Data Science, etc.) and tech stack (Laravel, React, Node.js, Python, Java, etc.).\n• The AI interviewer speaks questions aloud.\n• Speak your answer naturally into your microphone — speech recognition transcribes your words in real time.\n• Upon completion, you receive an immediate breakdown of concept accuracy, technical keywords, and clarity.', 'Start a Mock Interview', '/dashboard/interviews', '[\"mock-interview-supported-stacks\",\"mic-troubleshooting\"]', 30, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('mock_interviews', 'Mock AI Voice Interviews', 'Mic', 'What domains and tech stacks can I practice?', 'mock-interview-supported-stacks', 'AptRun supports 25+ industry tech stacks across all primary engineering disciplines:\n\n• **Full Stack & Backend**: Laravel, Node.js/Express, Python/Django, Java Spring Boot, Go, .NET, Ruby on Rails.\n• **Frontend**: React, Next.js, Vue.js, Angular, TypeScript.\n• **Data & AI**: Python Data Science, Machine Learning, SQL, Big Data.\n• **Mobile & Systems**: Flutter, Android Kotlin, iOS Swift, C++, DevOps & Cloud.', 'Explore Interview Tracks', '/dashboard/interviews/practice', '[\"how-mock-interviews-work\"]', 31, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('soft_skills', 'Soft Skills & Tests', 'CheckCircle2', 'How are Soft Skills tests structured on AptRun?', 'how-soft-skills-tests-work', 'AptRun provides 45 comprehensive test sets mimicking campus aptitude assessments:\n\n• **4 Key Categories**: Quantitative Aptitude, Logical Reasoning, Verbal English, and Situational Judgement.\n• **Zero Negative Marking**: All multiple-choice questions have equal weight.\n• **Real-Time Autosave**: Your selections are immediately saved to the server as you click options.\n• **Fullscreen & Anti-Copy**: Continuous fullscreen and anti-cheating protection are active throughout the test.', 'Take a Soft Skills Test', '/dashboard/soft-skills', '[\"fullscreen-strikes-explained\"]', 40, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('troubleshooting', 'Errors & Troubleshooting', 'AlertTriangle', 'I got a strike warning for exiting fullscreen. How does this work?', 'fullscreen-strikes-explained', 'Proctored assessments (Contests, Vault AI, Soft Skills) require continuous fullscreen mode:\n\n• Pressing Esc, switching browser tabs, or opening external apps triggers a **Strike Warning**.\n• You receive **2 warnings**. A **3rd strike** terminates and auto-submits your attempt.\n• If you accidentally exited fullscreen, click the **\'Resume Fullscreen\'** button immediately to return to the exam without further penalty.', 'Read Proctoring Guidelines', '/dashboard/soft-skills', '[\"mic-troubleshooting\",\"camera-troubleshooting\"]', 50, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('troubleshooting', 'Errors & Troubleshooting', 'AlertTriangle', 'Microphone or webcam not working in interview.', 'mic-troubleshooting', 'If your microphone or camera is not detected:\n\n1. **Browser Permission**: Click the **Lock icon** on the left of your browser address bar and verify that Camera and Microphone permissions are set to **Allow**.\n2. **Hardware Check**: Ensure your headset/mic is firmly plugged in and not muted via physical switch.\n3. **App Conflict**: Close other apps that might be using the camera (Zoom, Google Meet, Teams, Discord).\n4. **Refresh**: Reload the page to initialize the device test preview.', 'Test in Mock Interview', '/dashboard/interviews', '[\"camera-troubleshooting\"]', 51, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('troubleshooting', 'Errors & Troubleshooting', 'AlertTriangle', 'My test timer ran out before I clicked submit.', 'test-timer-expired', 'Don\'t panic! AptRun\'s server continuously auto-saves every answer you select.\n\nIf your timer reaches 0:00:\n• The system automatically submits all saved responses to the scoring engine.\n• No answers are lost, and your score will be generated accurately based on what was saved.', 'Check Your Results', '/dashboard/soft-skills', '[\"fullscreen-strikes-explained\"]', 52, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('billing', 'Plans & Account Settings', 'CreditCard', 'What is included in the AptRun Expert Plan?', 'expert-plan-features', 'The **AptRun Expert Plan** unlocks the complete career launchpad:\n\n• Unlimited DSA problem submissions in Practice Arena.\n• Full access to Project Lab and guided production projects.\n• Unlimited Mock AI Voice Interviews across all 25+ stacks.\n• Vault AI Interview eligibility and Mellow Vault candidate verification.\n• Comprehensive performance analytics and percentile benchmarking.', 'View Subscription Plans', '/dashboard/billing', '[\"what-is-aptrun\",\"direct-candidates-mellow-vault\"]', 60, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();
INSERT INTO `apt_bot_faqs` (`category`, `category_label`, `category_icon`, `question`, `slug`, `answer`, `action_label`, `action_url`, `related_slugs`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES ('billing', 'Plans & Account Settings', 'CreditCard', 'How do I update my profile, roll number, or graduation year?', 'update-profile-settings', 'You can update your personal information, department, roll number, and graduation year directly under your profile settings:\n\n• Go to **Dashboard > Settings** (or click your avatar at the bottom of the sidebar).\n• Update your academic year, graduation year (from 2018 onwards), and department.\n• Save changes to ensure placement eligibility criteria reflect your accurate profile.', 'Go to Settings', '/dashboard/settings', '[\"expert-plan-features\"]', 61, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`), `answer`=VALUES(`answer`), `action_label`=VALUES(`action_label`), `action_url`=VALUES(`action_url`), `related_slugs`=VALUES(`related_slugs`), `updated_at`=NOW();

SET FOREIGN_KEY_CHECKS = 1;
-- Done.